//method to print a chain of chars
void uart_print(const char* s)
{
	while(*s)
	{
		while(!(USART2_SR&(1<<7))){}
		USART2_DR=*s;
		s++;
	}
}
void ITM_SendChar(uint8_t ch)
{
    DEMCR |= (1 << 24);
    ITM_TRACE_EN |= (1 << 0);
    while(!(ITM_STIMULUS_PORT0 & 1));
    ITM_STIMULUS_PORT0 = ch;
}

extern "C" int __io_putchar(int ch)
{
    ITM_SendChar(ch);
    return ch;
}

void systick_init()
{
	STK_LOAD=15999;
	STK_VAL=0;
	STK_CTRL=(1<<0)|(1<<2);

}

